// ==========================================
// 1. TOGGLE KUNCI LOKASI SEKOLAH
// ==========================================
const toggle = document.getElementById("toggle-geofencing");
const fields = document.getElementById("geofencing-fields");

if (toggle && fields) {
    toggle.addEventListener("change", function () {
        if (this.checked) {
            fields.classList.remove("hidden");
            fields.classList.add("grid");
        } else {
            fields.classList.remove("grid");
            fields.classList.add("hidden");
        }
    });
}

// GPS Location lock
function getLokasiSekarang() {
    if (navigator.geolocation) {
        const btn = document.querySelector('button[onclick="getLokasiSekarang()"]');
        const origText = btn.innerHTML;
        btn.innerHTML = "⏳ Mengunci GPS...";
        btn.disabled = true;

        navigator.geolocation.getCurrentPosition(
            pos => {
                document.getElementById("lat-input").value = pos.coords.latitude;
                document.getElementById("lng-input").value = pos.coords.longitude;
                btn.innerHTML = origText;
                btn.disabled = false;
                Swal.fire({
                    icon: "success",
                    title: "Lokasi Dikunci",
                    text: "Titik koordinat GPS sekolah berhasil dimasukkan ke form!",
                    confirmButtonColor: "#e11d48",
                    customClass: {
                        popup: "rounded-[24px]",
                        confirmButton: "rounded-xl font-bold px-4 py-2"
                    }
                });
            },
            err => {
                Swal.fire({
                    icon: "error",
                    title: "Gagal Mengambil Lokasi",
                    text: err.message,
                    confirmButtonColor: "#e11d48",
                    customClass: {
                        popup: "rounded-[24px]",
                        confirmButton: "rounded-xl font-bold px-4 py-2"
                    }
                });
                btn.innerHTML = origText;
                btn.disabled = false;
            },
            { enableHighAccuracy: true }
        );
    }
}

// ==========================================
// 2. CUSTOM DROPDOWN KATEGORI
// ==========================================
function initCustomCategoryDropdown() {
    const displayCategory = document.getElementById("display_category");
    const hiddenCategory = document.getElementById("category");
    const dropdownCategory = document.getElementById("dropdown-category");
    const chevron = document.getElementById("category-chevron");
    const customContainer = document.getElementById("container-custom-category");
    const customInput = document.getElementById("custom_category");

    if (!displayCategory || !hiddenCategory || !dropdownCategory) return;

    displayCategory.addEventListener("click", function (e) {
        e.stopPropagation();
        const isHidden = dropdownCategory.classList.contains("hidden");
        closeAllCustomPickers();
        if (isHidden) {
            dropdownCategory.classList.remove("hidden");
            if (chevron) chevron.classList.add("rotate-180");
        }
    });

    dropdownCategory.querySelectorAll(".category-item").forEach(item => {
        item.addEventListener("click", function (e) {
            e.stopPropagation();
            const val = this.getAttribute("data-val");
            hiddenCategory.value = val;
            displayCategory.value = val;

            // Highlight check icon
            dropdownCategory.querySelectorAll(".category-item").forEach(i => {
                const check = i.querySelector(".check-icon");
                if (check) check.classList.add("hidden");
            });
            const activeCheck = this.querySelector(".check-icon");
            if (activeCheck) activeCheck.classList.remove("hidden");

            closeAllCustomPickers();

            // Toggle custom category input
            if (val === "Lainnya") {
                if (customContainer) {
                    customContainer.classList.remove("hidden");
                    if (customInput) setTimeout(() => customInput.focus(), 80);
                }
            } else {
                if (customContainer) {
                    customContainer.classList.add("hidden");
                    if (customInput) customInput.value = "";
                }
            }
        });
    });
}

// ==========================================
// 3. CUSTOM CALENDAR DATEPICKER (INDONESIA)
// ==========================================
function initCustomCalendar() {
    const displayDate = document.getElementById("display_event_date");
    const hiddenDate = document.getElementById("event_date");
    const picker = document.getElementById("picker-event-date");

    const prevBtn = document.getElementById("cal-prev");
    const nextBtn = document.getElementById("cal-next");
    const todayBtn = document.getElementById("cal-btn-today");

    // Header buttons & labels
    const btnMonth = document.getElementById("cal-btn-month");
    const labelMonth = document.getElementById("cal-label-month");
    const iconMonth = document.getElementById("cal-icon-month");

    const btnYear = document.getElementById("cal-btn-year");
    const labelYear = document.getElementById("cal-label-year");
    const iconYear = document.getElementById("cal-icon-year");
    const inputYear = document.getElementById("cal-input-year");

    // Views
    const viewDays = document.getElementById("cal-view-days");
    const viewMonths = document.getElementById("cal-view-months");
    const viewYears = document.getElementById("cal-view-years");

    // Grids
    const daysGrid = document.getElementById("cal-days-grid");
    const monthsGrid = document.getElementById("cal-months-grid");
    const yearsGrid = document.getElementById("cal-years-grid");

    if (!displayDate || !hiddenDate || !picker) return;

    const monthNames = [
        "Januari", "Februari", "Maret", "April", "Mei", "Juni",
        "Juli", "Agustus", "September", "Oktober", "November", "Desember"
    ];

    let selectedDate = new Date();
    if (hiddenDate.value && hiddenDate.value.includes("-")) {
        const parts = hiddenDate.value.split("-");
        selectedDate = new Date(parseInt(parts[0]), parseInt(parts[1]) - 1, parseInt(parts[2]));
    }

    let viewYear = selectedDate.getFullYear();
    let viewMonth = selectedDate.getMonth();
    let currentMode = "days"; // "days" | "months" | "years"

    function updateHeaderLabels() {
        if (labelMonth) labelMonth.textContent = monthNames[viewMonth];
        if (labelYear) labelYear.textContent = viewYear;
    }

    function updateFormValues() {
        const yStr = String(selectedDate.getFullYear());
        const mStr = String(selectedDate.getMonth() + 1).padStart(2, "0");
        const dStr = String(selectedDate.getDate()).padStart(2, "0");

        hiddenDate.value = `${yStr}-${mStr}-${dStr}`;
        displayDate.value = `${selectedDate.getDate()} ${monthNames[selectedDate.getMonth()]} ${yStr}`;
    }

    function switchMode(mode) {
        currentMode = mode;

        if (mode === "days") {
            if (viewDays) viewDays.classList.remove("hidden");
            if (viewMonths) viewMonths.classList.add("hidden");
            if (viewYears) viewYears.classList.add("hidden");

            if (btnMonth) btnMonth.className = "px-2.5 py-1.5 rounded-xl font-extrabold text-slate-800 hover:bg-slate-100 transition flex items-center gap-1 text-xs tracking-wide";
            if (btnYear) btnYear.className = "px-2.5 py-1.5 rounded-xl font-extrabold text-slate-800 hover:bg-slate-100 transition flex items-center gap-1 text-xs tracking-wide";
            if (iconMonth) iconMonth.classList.remove("rotate-180", "text-rose-600");
            if (iconYear) iconYear.classList.remove("rotate-180", "text-rose-600");

            renderDays();
        } else if (mode === "months") {
            if (viewDays) viewDays.classList.add("hidden");
            if (viewMonths) viewMonths.classList.remove("hidden");
            if (viewYears) viewYears.classList.add("hidden");

            if (btnMonth) btnMonth.className = "px-2.5 py-1.5 rounded-xl font-extrabold text-rose-600 bg-rose-50 ring-1 ring-rose-200 transition flex items-center gap-1 text-xs tracking-wide";
            if (btnYear) btnYear.className = "px-2.5 py-1.5 rounded-xl font-extrabold text-slate-800 hover:bg-slate-100 transition flex items-center gap-1 text-xs tracking-wide";
            if (iconMonth) {
                iconMonth.classList.add("rotate-180", "text-rose-600");
            }
            if (iconYear) {
                iconYear.classList.remove("rotate-180", "text-rose-600");
            }

            renderMonths();
        } else if (mode === "years") {
            if (viewDays) viewDays.classList.add("hidden");
            if (viewMonths) viewMonths.classList.add("hidden");
            if (viewYears) viewYears.classList.remove("hidden");

            if (btnMonth) btnMonth.className = "px-2.5 py-1.5 rounded-xl font-extrabold text-slate-800 hover:bg-slate-100 transition flex items-center gap-1 text-xs tracking-wide";
            if (btnYear) btnYear.className = "px-2.5 py-1.5 rounded-xl font-extrabold text-rose-600 bg-rose-50 ring-1 ring-rose-200 transition flex items-center gap-1 text-xs tracking-wide";
            if (iconMonth) {
                iconMonth.classList.remove("rotate-180", "text-rose-600");
            }
            if (iconYear) {
                iconYear.classList.add("rotate-180", "text-rose-600");
            }

            renderYears();
        }
    }

    function renderDays() {
        if (!daysGrid) return;
        updateHeaderLabels();
        daysGrid.innerHTML = "";

        const firstDayIndex = new Date(viewYear, viewMonth, 1).getDay();
        const daysInMonth = new Date(viewYear, viewMonth + 1, 0).getDate();
        const today = new Date();

        for (let i = 0; i < firstDayIndex; i++) {
            const blank = document.createElement("span");
            blank.className = "py-2";
            daysGrid.appendChild(blank);
        }

        for (let d = 1; d <= daysInMonth; d++) {
            const btn = document.createElement("button");
            btn.type = "button";
            btn.textContent = d;

            const isSelected =
                selectedDate.getFullYear() === viewYear &&
                selectedDate.getMonth() === viewMonth &&
                selectedDate.getDate() === d;

            const isToday =
                today.getFullYear() === viewYear &&
                today.getMonth() === viewMonth &&
                today.getDate() === d;

            let btnClass = "w-full py-2 rounded-xl text-xs font-semibold transition ";
            if (isSelected) {
                btnClass += "bg-rose-600 text-white font-bold shadow-sm";
            } else if (isToday) {
                btnClass += "border border-rose-300 text-rose-600 font-bold hover:bg-rose-50";
            } else {
                btnClass += "text-slate-700 hover:bg-slate-100";
            }
            btn.className = btnClass;

            btn.onclick = function (e) {
                e.stopPropagation();
                selectedDate = new Date(viewYear, viewMonth, d);
                updateFormValues();
                renderDays();
                closeAllCustomPickers();
            };

            daysGrid.appendChild(btn);
        }
    }

    function renderMonths() {
        if (!monthsGrid) return;
        updateHeaderLabels();
        monthsGrid.innerHTML = "";
        const today = new Date();

        monthNames.forEach((name, idx) => {
            const btn = document.createElement("button");
            btn.type = "button";
            btn.textContent = name;

            const isSelected =
                selectedDate.getFullYear() === viewYear &&
                selectedDate.getMonth() === idx;

            const isCurrentMonth =
                today.getFullYear() === viewYear &&
                today.getMonth() === idx;

            let btnClass = "w-full py-2.5 rounded-xl text-xs font-semibold transition ";
            if (isSelected) {
                btnClass += "bg-rose-600 text-white font-bold shadow-sm";
            } else if (isCurrentMonth) {
                btnClass += "border border-rose-300 text-rose-600 font-bold hover:bg-rose-50";
            } else {
                btnClass += "text-slate-700 hover:bg-slate-100";
            }
            btn.className = btnClass;

            btn.onclick = function (e) {
                e.stopPropagation();
                viewMonth = idx;

                // Adjust day if exceeds days in new month (e.g. Jan 31 -> Feb 28)
                const currentDay = selectedDate.getDate();
                const maxDays = new Date(viewYear, idx + 1, 0).getDate();
                const safeDay = Math.min(currentDay, maxDays);
                selectedDate = new Date(viewYear, idx, safeDay);
                updateFormValues();

                switchMode("days");
            };

            monthsGrid.appendChild(btn);
        });
    }

    function applyYear(y) {
        viewYear = y;
        const currentDay = selectedDate.getDate();
        const maxDays = new Date(y, viewMonth + 1, 0).getDate();
        const safeDay = Math.min(currentDay, maxDays);
        selectedDate = new Date(y, viewMonth, safeDay);
        updateFormValues();
        updateHeaderLabels();
        if (inputYear) inputYear.value = y;
    }

    function renderYears() {
        if (!yearsGrid) return;
        updateHeaderLabels();
        yearsGrid.innerHTML = "";
        const today = new Date();

        if (inputYear) {
            inputYear.value = viewYear;
        }

        // Rentang tahun dinamis tanpa batas kaku (minimal 1950 s/d 2099, atau disesuaikan dengan viewYear)
        const startYear = Math.min(1950, viewYear - 30);
        const endYear = Math.max(2099, viewYear + 30);

        let activeYearBtn = null;

        for (let y = startYear; y <= endYear; y++) {
            const btn = document.createElement("button");
            btn.type = "button";
            btn.textContent = y;

            const isSelected = selectedDate.getFullYear() === y;
            const isCurrentYear = today.getFullYear() === y;

            let btnClass = "w-full py-2.5 rounded-xl text-xs font-semibold transition ";
            if (isSelected) {
                btnClass += "bg-rose-600 text-white font-bold shadow-sm";
                activeYearBtn = btn;
            } else if (isCurrentYear) {
                btnClass += "border border-rose-300 text-rose-600 font-bold hover:bg-rose-50";
            } else {
                btnClass += "text-slate-700 hover:bg-slate-100";
            }
            btn.className = btnClass;

            btn.onclick = function (e) {
                e.stopPropagation();
                applyYear(y);
                switchMode("days");
            };

            yearsGrid.appendChild(btn);
        }

        if (activeYearBtn) {
            setTimeout(() => {
                yearsGrid.scrollTop = activeYearBtn.offsetTop - yearsGrid.offsetTop - 50;
            }, 50);
        }
    }

    if (inputYear) {
        inputYear.addEventListener("input", function () {
            const val = parseInt(this.value);
            if (!isNaN(val) && val >= 1900 && val <= 2200) {
                applyYear(val);
                renderYears();
            }
        });

        inputYear.addEventListener("keydown", function (e) {
            if (e.key === "Enter") {
                e.preventDefault();
                const val = parseInt(this.value);
                if (!isNaN(val) && val >= 1900 && val <= 2200) {
                    applyYear(val);
                }
                switchMode("days");
            }
        });
    }

    if (btnMonth) {
        btnMonth.addEventListener("click", function (e) {
            e.stopPropagation();
            if (currentMode === "months") {
                switchMode("days");
            } else {
                switchMode("months");
            }
        });
    }

    if (btnYear) {
        btnYear.addEventListener("click", function (e) {
            e.stopPropagation();
            if (currentMode === "years") {
                switchMode("days");
            } else {
                switchMode("years");
            }
        });
    }

    displayDate.addEventListener("click", function (e) {
        e.stopPropagation();
        const isHidden = picker.classList.contains("hidden");
        closeAllCustomPickers();
        if (isHidden) {
            picker.classList.remove("hidden");
            viewYear = selectedDate.getFullYear();
            viewMonth = selectedDate.getMonth();
            switchMode("days");
        }
    });

    if (prevBtn) {
        prevBtn.addEventListener("click", function (e) {
            e.stopPropagation();
            if (currentMode === "days") {
                viewMonth--;
                if (viewMonth < 0) {
                    viewMonth = 11;
                    viewYear--;
                }
                renderDays();
            } else if (currentMode === "months") {
                viewYear--;
                updateHeaderLabels();
                renderMonths();
            } else if (currentMode === "years") {
                viewYear -= 10;
                applyYear(viewYear);
                renderYears();
            }
        });
    }

    if (nextBtn) {
        nextBtn.addEventListener("click", function (e) {
            e.stopPropagation();
            if (currentMode === "days") {
                viewMonth++;
                if (viewMonth > 11) {
                    viewMonth = 0;
                    viewYear++;
                }
                renderDays();
            } else if (currentMode === "months") {
                viewYear++;
                updateHeaderLabels();
                renderMonths();
            } else if (currentMode === "years") {
                viewYear += 10;
                applyYear(viewYear);
                renderYears();
            }
        });
    }

    if (todayBtn) {
        todayBtn.addEventListener("click", function (e) {
            e.stopPropagation();
            const now = new Date();
            selectedDate = new Date(now.getFullYear(), now.getMonth(), now.getDate());
            viewYear = now.getFullYear();
            viewMonth = now.getMonth();
            updateFormValues();
            switchMode("days");
            closeAllCustomPickers();
        });
    }

    switchMode("days");
}

// ==========================================
// 4. CUSTOM 24-HOUR TIME PICKER (WIB, WITA, WIT)
// ==========================================
function init24HourTimePicker(prefix, defaultHour, defaultMinute, defaultZone) {
    const displayInput = document.getElementById(`display_${prefix}`);
    const hiddenInput = document.getElementById(`${prefix}`);
    const pickerId = `picker-${prefix.replace('_', '-')}`;
    const picker = document.getElementById(pickerId);
    const preview = document.getElementById(`preview-${prefix.replace('_', '-')}`);
    const hoursContainer = document.getElementById(`hours-${prefix.replace('_', '-')}`);
    const minutesContainer = document.getElementById(`minutes-${prefix.replace('_', '-')}`);
    const zoneContainer = document.getElementById(`zone-${prefix.replace('_', '-')}`);

    if (!displayInput || !hiddenInput || !picker) return;

    let currentHour = defaultHour;
    let currentMinute = defaultMinute;
    let currentZone = defaultZone || "WIB";

    if (hiddenInput.value && hiddenInput.value.includes(':')) {
        const parts = hiddenInput.value.trim().split(':');
        currentHour = parts[0].padStart(2, '0');
        currentMinute = (parts[1] || '00').substring(0, 2).padStart(2, '0');
    }

    hoursContainer.innerHTML = '';
    for (let i = 0; i < 24; i++) {
        const hStr = String(i).padStart(2, '0');
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.textContent = hStr;
        btn.className = `w-full py-2 rounded-xl text-xs font-semibold transition ${
            hStr === currentHour ? 'bg-rose-600 text-white font-bold shadow-sm' : 'text-slate-700 hover:bg-slate-100'
        }`;
        btn.onclick = function (e) {
            e.stopPropagation();
            currentHour = hStr;
            updatePickerState();
        };
        hoursContainer.appendChild(btn);
    }

    minutesContainer.innerHTML = '';
    for (let i = 0; i < 60; i++) {
        const mStr = String(i).padStart(2, '0');
        const btn = document.createElement('button');
        btn.type = 'button';
        btn.textContent = mStr;
        btn.className = `w-full py-2 rounded-xl text-xs font-semibold transition ${
            mStr === currentMinute ? 'bg-rose-600 text-white font-bold shadow-sm' : 'text-slate-700 hover:bg-slate-100'
        }`;
        btn.onclick = function (e) {
            e.stopPropagation();
            currentMinute = mStr;
            updatePickerState();
        };
        minutesContainer.appendChild(btn);
    }

    zoneContainer.querySelectorAll('button').forEach(btn => {
        btn.onclick = function (e) {
            e.stopPropagation();
            currentZone = this.getAttribute('data-val');
            updatePickerState();
        };
    });

    function updatePickerState() {
        hiddenInput.value = `${currentHour}:${currentMinute}`;
        displayInput.value = `${currentHour}:${currentMinute} ${currentZone}`;
        preview.textContent = `${currentHour}:${currentMinute} ${currentZone}`;

        hoursContainer.querySelectorAll('button').forEach(btn => {
            if (btn.textContent === currentHour) {
                btn.className = 'w-full py-2 rounded-xl text-xs font-bold bg-rose-600 text-white shadow-sm';
            } else {
                btn.className = 'w-full py-2 rounded-xl text-xs font-semibold text-slate-700 hover:bg-slate-100';
            }
        });

        minutesContainer.querySelectorAll('button').forEach(btn => {
            if (btn.textContent === currentMinute) {
                btn.className = 'w-full py-2 rounded-xl text-xs font-bold bg-rose-600 text-white shadow-sm';
            } else {
                btn.className = 'w-full py-2 rounded-xl text-xs font-semibold text-slate-700 hover:bg-slate-100';
            }
        });

        zoneContainer.querySelectorAll('button').forEach(btn => {
            if (btn.getAttribute('data-val') === currentZone) {
                btn.className = 'zone-btn w-full py-2.5 rounded-xl font-bold transition text-xs bg-rose-600 text-white shadow-sm';
            } else {
                btn.className = 'zone-btn w-full py-2.5 rounded-xl font-bold transition text-xs bg-slate-50 text-slate-700 hover:bg-slate-100';
            }
        });
    }

    function scrollToSelected() {
        const activeH = hoursContainer.querySelector('.bg-rose-600');
        if (activeH) hoursContainer.scrollTop = activeH.offsetTop - hoursContainer.offsetTop - 50;
        const activeM = minutesContainer.querySelector('.bg-rose-600');
        if (activeM) minutesContainer.scrollTop = activeM.offsetTop - minutesContainer.offsetTop - 50;
    }

    displayInput.addEventListener('click', function (e) {
        e.stopPropagation();
        const isHidden = picker.classList.contains('hidden');
        closeAllCustomPickers();
        if (isHidden) {
            picker.classList.remove('hidden');
            setTimeout(scrollToSelected, 60);
        }
    });

    updatePickerState();
}

// ==========================================
// 5. UNIFIED CLOSE HANDLER
// ==========================================
function closeAllCustomPickers() {
    const dropdownCat = document.getElementById("dropdown-category");
    const chevron = document.getElementById("category-chevron");
    if (dropdownCat) dropdownCat.classList.add("hidden");
    if (chevron) chevron.classList.remove("rotate-180");

    const pickerDate = document.getElementById("picker-event-date");
    if (pickerDate) pickerDate.classList.add("hidden");

    document.querySelectorAll('[id^="picker-start-time"], [id^="picker-end-time"]').forEach(p => p.classList.add('hidden'));
}

document.addEventListener('DOMContentLoaded', function () {
    initCustomCategoryDropdown();
    initCustomCalendar();
    init24HourTimePicker('start_time', '07', '30', 'WIB');
    init24HourTimePicker('end_time', '15', '00', 'WIB');

    document.addEventListener('click', function (e) {
        if (
            !e.target.closest('#container-category') &&
            !e.target.closest('#container-event-date') &&
            !e.target.closest('#container-start-time') &&
            !e.target.closest('#container-end-time')
        ) {
            closeAllCustomPickers();
        }
    });
});
